        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("grade must be A, B or C");
        }
        person.set(new PersonRequest(name, grade));
    }
}
